package com.bank.placement;

import java.util.logging.*;

public class PlacementDemo {
    private static final Logger log = Logger.getLogger("Placement");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        DeploymentInfoService info = new DeploymentInfoService("ap-south-1", "ap-south-1b");
        StatementLocationService loc = new StatementLocationService();

        log.info(() -> "Service running in Region " + info.region() + " AZ " + info.availabilityZone());
        String bucketRegion = loc.chooseRegionForCustomer("IN");
        log.info(() -> "Rajesh (India) statements stored in Region " + bucketRegion);
        log.info(() -> "PDF served from nearest Edge Location: " + loc.describeEdge("Mumbai"));
    }
}

// ─── Would be in DeploymentInfoService.java ───
class DeploymentInfoService {
    private final String region;
    private final String az;
    DeploymentInfoService(String region, String az) { this.region = region; this.az = az; }
    String region() { return region; }
    String availabilityZone() { return az; }
}

// ─── Would be in StatementLocationService.java ───
class StatementLocationService {
    // RBI rule: Indian customer data must stay in India.
    String chooseRegionForCustomer(String countryCode) {
        return "IN".equals(countryCode) ? "ap-south-1" : "eu-west-1";
    }
    String describeEdge(String city) {
        return "CloudFront edge near " + city + " (cache hit avoids Region round-trip)";
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
